interface Alpha {
    default void hello() { System.out.print("Alpha "); }
}
interface Beta {
    default void hello() { System.out.print("Beta "); }
}
class Combined implements Alpha, Beta {
    public void hello() {
        Alpha.super.hello();
        System.out.print("Combined ");
    }
}
public class Main {
    public static void main(String[] args) {
        new Combined().hello();
    }
}

interface Greeting {
    default void greet() { System.out.print("Interface Greet "); }
}
class Base {
    public void greet() { System.out.print("Base Greet "); }
}
class Sub extends Base implements Greeting {}
public class Main {
    public static void main(String[] args) {
        Greeting g = new Sub();
        g.greet();
    }
}

