abstract class Shape {
    String color;
    Shape(String color) {
        this.color = color;
        System.out.print("Shape:" + color + " ");
    }
}
class Circle extends Shape {
    Circle(String color) {
        super(color);
        System.out.print("Circle ");
    }
}
public class Main {
    public static void main(String[] args) {
        new Circle("Red");
    }
}

@FunctionalInterface
interface Transformer {
    int transform(int x);
    int reverse(int x);
}

abstract class Greeter {
    abstract void sayHi();
    void sayBye() { System.out.print("Bye "); }
}
public class Main {
    public static void main(String[] args) {
        Greeter g = new Greeter() {
            void sayHi() { System.out.print("Hi "); }
        };
        g.sayHi();
        g.sayBye();
    }
}

abstract class Beverage {
    final void prepareRecipe() {
        boilWater();
        brew();
        pourInCup();
    }
    void boilWater() { System.out.print("Boil "); }
    void pourInCup() { System.out.print("Pour "); }
    abstract void brew();
}
class Tea extends Beverage {
    void brew() { System.out.print("SteepTea "); }
}
public class Main {
    public static void main(String[] args) {
        Beverage b = new Tea();
        b.prepareRecipe();
    }
}

